B.bKO=new A.mg(B.aPd,B.aFC,B.aKC,B.aGN,B.aNz,B.aMV,"\uac19\uc740 \uc9c8\ubb38\uc740 \uc22b\uc790\uac00 \ub2ec\ub77c\uc84c\uc744 \ub54c \ub2e4\uc2dc \ubcf4\uc790.","\uc9c0\uae08\uae4c\uc9c0\ub294 \uc190\uc2e4\uc774\uc57c. \uc5b4\ub5a4 \ub3c8\uc744 \ubc88 \uac74\uc9c0 \uc22b\uc790\ubd80\ud130 \ub9de\ucdb0.","\uc9c0\uae08\uae4c\uc9c0\ub294 \uc218\uc775\uc774\uc57c. \ub2e4\ub978 \ub370\uc11c \uc783\uc740 \uac70\uba74 \uadf8\uac78 \ub9d0\ud574 \uc918.","\uc624\ub298\uc740 \uc190\ud574\uc778\ub370 \ubc8c\uc5c8\ub2e4\uace0? \uc624\ub298 \uc22b\uc790 \ub2e4\uc2dc \ubd10.","\uc624\ub298\uc740 \ubc8c\uc5c8\ub294\ub370 \uc783\uc5c8\ub2e4\uace0? \uc804\uccb4 \uc598\uae30\uba74 \uadf8\ub807\uac8c \ub9d0\ud574.")
B.aQC=s(["\uc751, \uc77d\uc5c8\uc5b4.","\ub124 \uc598\uae30\ub294 \uc801\uc5b4 \ub458\uac8c.","\ubb34\uc2a8 \ub73b\uc778\uc9c0 \uc54c\uaca0\uc5b4.","\ub05d\uae4c\uc9c0 \uc77d\uc5c8\uc5b4.","\ub124\uac00 \uba3c\uc800 \ub9d0\ud574 \uc918\uc11c \uace0\ub9c8\uc6cc.","\uc6b0\ub9ac\uac00 \uc313\uc740 \uae30\ub85d\uc774 \uc788\uc73c\ub2c8\uae4c \ubbff\uc744\uac8c."],t.s)
B.aF7=s(["\uc544\uc9c1 \uc624\ub298 \uacb0\uacfc\ub3c4 \uc548 \ub098\uc654\ub294\ub370 \ubbf8\ub9ac \uc815\ud558\uae34 \uc774\ub978 \uac83 \uac19\uc544.","\uc624\ub298\uc740 \uc7a5 \uc26c\ub2c8\uae4c \uc804\uc5d0 \uc801\uc5b4 \ub454 \uac70\ub098 \uac19\uc774 \ubcfc\uae4c?","\uc624\ub298\uc740 \uac70\uc758 \uadf8\ub300\ub85c\ub124.","\uc624\ub298\ub3c4 \ubc8c\uc5c8\uace0 \uc9c0\uae08\uae4c\uc9c0\ub3c4 \ud50c\ub7ec\uc2a4\ub77c \ub2e4\ud589\uc774\uc57c.","\uc624\ub298\uc740 \ubc8c\uc5c8\uc9c0\ub9cc \uc544\uc9c1 \ubcf8\uc804 \uc544\ub798\ub124. \uadf8\ub798\ub3c4 \uc870\uae08 \ub3cc\uc544\uc654\uc5b4.","\uc624\ub298\uc740 \uc783\uc5c8\uc9c0\ub9cc \uc9c0\uae08\uae4c\uc9c0 \ubc88 \ub3c8\uc740 \ub0a8\uc544 \uc788\uc5b4.","\uc624\ub298\ub3c4 \uc783\uc5c8\uace0 \uc544\uc9c1 \ubcf8\uc804 \uc544\ub798\ub77c \uc18d\uc0c1\ud558\uaca0\ub2e4."],t.s)
B.aGY=s(["\uc804\uc5d0 \uc815\ud55c \uc120\ubcf4\ub2e4 \ub354 \uc783\uc740 \uac74 \uc544\ub2cc\uc9c0 \uba3c\uc800 \ubcfc\uae4c?","\uc624\ub298 \uc783\uc740 \uc774\uc720\ub791 \uadf8\ub54c \ubb58 \ubbff\uc5c8\ub294\uc9c0 \uac19\uc774 \uc801\uc5b4 \ub450\uc790."],t.s)
B.aPf=s(["\ubc88 \uac74 \ub2e4\ud589\uc774\uc57c. \uadf8 \ud68c\uc0ac\uac00 \uc804\uc5d0 \ud55c \uc57d\uc18d\ub3c4 \uc9c0\ucf30\ub294\uc9c0 \ubcf4\uc790.","\uc624\ub298 \uc798\ub41c \uac74 \uc801\uc5b4 \ub450\uc790. \ub2e4\uc74c\uc5d0\ub3c4 \uac19\uc740 \uc774\uc720\uc778\uc9c0 \ubcfc \uc218 \uc788\uac8c."],t.s)
